import unittest
from decimal import getcontext
from cash import cash_total

class Cash(unittest.TestCase):
    def test_steps(self):
        for value, expected in [('1.02','1.00'),('1.025','1.05'),('-1.025','-1.05'),('1.075','1.10'),('12.99','13.00'),('0','0.00'),('-0.001','0.00'),('999999999999.975','1000000000000.00')]:
            self.assertEqual(cash_total(value), expected)
    def test_context(self):
        before = getcontext().copy()
        old = getcontext().prec
        try:
            getcontext().prec = 6
            self.assertEqual(cash_total('12345678.025'), '12345678.05')
            self.assertEqual(getcontext().prec, 6)
        finally:
            getcontext().prec = old
        self.assertEqual(getcontext().rounding, before.rounding)

if __name__ == '__main__':
    unittest.main()

