from decimal import Decimal, localcontext, ROUND_HALF_UP

def cash_total(amount):
    value = Decimal(amount)
    with localcontext() as ctx:
        ctx.prec = max(28, len(value.as_tuple().digits) + abs(value.as_tuple().exponent) + 8)
        rounded = (value / Decimal('0.05')).quantize(Decimal('1'), rounding=ROUND_HALF_UP) * Decimal('0.05')
        if rounded == 0:
            rounded = abs(rounded)
        return format(rounded, '.2f')

